const ib=(label,action,id,ic,disabled=false)=>`<button class="icon-btn" aria-label="${h(label)}" title="${h(label)}" data-action="${action}" data-id="${h(id)}" ${disabled?'disabled':''}>${icon(ic,true)}</button>`;
